-- ============================================================================
-- create_extensions_schemas_enums
-- Extensions, schemas and enum types. Applied first; everything else depends on it.
-- ============================================================================

-- Schema provenance
-- -----------------
-- These layered migrations were split, unchanged, from one dump that was
-- generated by applying the original migration chain to a clean database.
-- Three classes of object pg_dump does not emit are included explicitly:
-- extensions (CREATE EXTENSION), RBAC reference data (roles, permissions and
-- role_permissions, in seed_rbac_reference_data) and pg_cron jobs (in
-- schedule_cron_jobs). Multitenancy: SME data lives in "public", agency data in
-- "agency"; Row Level Security is the tenant-isolation boundary.

-- ---------------------------------------------------------------------------
-- 1. Extensions
-- ---------------------------------------------------------------------------
CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS pg_cron;

-- ---------------------------------------------------------------------------
-- 2. Schema: tables, functions, views, indexes, triggers and RLS policies
-- ---------------------------------------------------------------------------



SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;


CREATE SCHEMA IF NOT EXISTS "agency";


ALTER SCHEMA "agency" OWNER TO "postgres";


COMMENT ON SCHEMA "agency" IS 'Separate schema for agency users managing multiple clients. SME users remain in public schema for zero risk to existing functionality.';



CREATE SCHEMA IF NOT EXISTS "public";


ALTER SCHEMA "public" OWNER TO "pg_database_owner";


COMMENT ON SCHEMA "public" IS 'get_top_performing_outputs dropped - requires rewrite to cast double precision to numeric. Migration 172.';



CREATE TYPE "public"."business_model_enum" AS ENUM (
    'B2B',
    'B2C',
    'B2B2C',
    'Subscription',
    'Marketplace',
    'Freemium',
    'Transaction-based',
