    '51-200 employees',
    '201-500 employees',
    '501-1000 employees',
    '1000+ employees'
);


ALTER TYPE "public"."company_size_enum" OWNER TO "postgres";


COMMENT ON TYPE "public"."company_size_enum" IS 'User-friendly company size ranges aligned with frontend';



