SET default_tablespace = '';

SET default_table_access_method = "heap";








-- ---------------------------------------------------------------------------
-- 3. RBAC reference data
--    Created by the original migration chain, NOT by seed.sql. Without this
--    the application's authorization model is empty.
-- ---------------------------------------------------------------------------
--
-- PostgreSQL database dump
--


-- Dumped from database version 17.6
-- Dumped by pg_dump version 17.6

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET transaction_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

--
-- Data for Name: permissions; Type: TABLE DATA; Schema: public; Owner: -
--

-- The original chain inserted this data before these triggers existed.
-- A consolidated baseline creates the schema first, so the triggers would
-- fire on load. Disable them for this trusted reference data only.
SET session_replication_role = replica;


--
-- PostgreSQL database dump complete
--




SET session_replication_role = origin;

-- ---------------------------------------------------------------------------
-- 6. Restore search_path
--    pg_dump sets search_path to empty for its own session
--    (set_config('search_path', '', false) — session-scoped, not local).
--    Supabase applies migrations and seed data over the same session, so
--    leaving it empty breaks seed.sql's unqualified statements, e.g.
--    "REFRESH MATERIALIZED VIEW org_metrics_cache".
-- ---------------------------------------------------------------------------
SET search_path TO "public", "agency", "extensions";